import { CommonModule } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { AuthService } from '../core/services/auth.service';

@Component({
  selector: 'app-shell',
  standalone: true,
  imports: [CommonModule, RouterOutlet, RouterLink, RouterLinkActive],
  template: `
    <div class="app-shell">
      <aside class="sidebar">
        <div class="brand-panel">
          <img class="brand-logo" src="assets/logo.webp" alt="Logo JLMoraga" />
          <span class="eyebrow">Control operativo</span>
          <h1>Neumaticos JLMoraga</h1>
          <p>Trazabilidad visual para deposito, tractores y semis.</p>
          <div class="brand-highlight">
            <strong>Operacion clara</strong>
            <span>Stock, ubicacion actual y movimientos en una sola vista.</span>
          </div>
        </div>

        <nav class="nav-links">
          <a routerLink="/dashboard" routerLinkActive="active">Dashboard</a>
          <a routerLink="/gomas" routerLinkActive="active">Gomas</a>
          <a routerLink="/movimientos" routerLinkActive="active">Movimientos</a>
          <a routerLink="/recursos" routerLinkActive="active">Recursos</a>
          <a *ngIf="authService.getCurrentUser()?.role === 'ADMIN'" routerLink="/usuarios" routerLinkActive="active">Usuarios</a>
        </nav>

        <div class="user-panel" *ngIf="authService.getCurrentUser() as user">
          <div>
            <strong>{{ user.name }}</strong>
            <span>{{ user.email }}</span>
          </div>
          <button class="ghost-button" type="button" (click)="logout()">Salir</button>
        </div>
      </aside>

      <main class="content-area">
        <section class="content-intro" *ngIf="authService.getCurrentUser() as user">
          <div>
            <span class="eyebrow">Panel activo</span>
            <h2>Bienvenido, {{ user.name }}</h2>
            <p>Gestiona stock, movimientos y usuarios con una vista mas clara y ordenada.</p>
          </div>
          <div class="intro-badge">
            <span>Rol</span>
            <strong>{{ user.role === 'ADMIN' ? 'Administrador' : 'Operador' }}</strong>
          </div>
        </section>
        <router-outlet></router-outlet>
      </main>
    </div>
  `,
})
export class ShellComponent implements OnInit {
  readonly authService = inject(AuthService);
  private readonly router = inject(Router);

  ngOnInit(): void {
    if (this.authService.getToken()) {
      this.authService.fetchMe().subscribe({
        error: () => {
          this.authService.logout();
          this.router.navigate(['/login']);
        },
      });
    }
  }

  logout(): void {
    this.authService.logout();
    this.router.navigate(['/login']);
  }
}
